  /**
   * Method under test: {@link EntityBuilder#attribute(String, Integer)}
   */
  @Test
  public void testAttribute() throws EntityXMLGeneratorException {
    // Arrange
    EntityBuilder forNestedEntityResult = EntityBuilder.forNestedEntity("Type");

    // Act
    EntityBuilder actualAttributeResult = forNestedEntityResult.attribute("Name", 42);

    // Assert
    assertEquals("<entity type=\"Type\" version=\"1.0\"><attribute name=\"Name\" type=\"org.symphony.oss.number.int\""
        + " value=\"42\"/></entity>", forNestedEntityResult.generateXML());
    assertSame(forNestedEntityResult, actualAttributeResult);
  }

