  /**
   * Method under test: {@link EntityBuilder#attribute(String, String)}
   */
  @Test
  public void testAttribute5() throws EntityXMLGeneratorException {
    // Arrange
    EntityBuilder forNestedEntityResult = EntityBuilder.forNestedEntity("Type");

    // Act
    EntityBuilder actualAttributeResult = forNestedEntityResult.attribute("Name",
        "<  a  href  =  \"http://UUUUUUUUUUUU//UU&amp;&amp;//UU&amp;&amp;\"  >xx</a>");

    // Assert
    assertEquals(
        "<entity type=\"Type\" version=\"1.0\"><attribute name=\"Name\" type=\"org.symphonyoss.string\" value=\"&amp;lt;"
            + "  a  href  =  &amp;quot;&lt;a href=&quot;http://UUUUUUUUUUUU//UU&amp;amp;amp&quot;&gt;http://UUUUUUUUUUUU"
            + "//UU&amp;amp;amp&lt;/a&gt;;&amp;amp;amp;//UU&amp;amp;amp;&amp;amp;amp;&amp;quot;  &amp;gt;xx&amp;lt;"
            + "/a&amp;gt;\"/></entity>",
        forNestedEntityResult.generateXML());
    assertSame(forNestedEntityResult, actualAttributeResult);
  }

